public sealed record WorkUnit(int Id);

// В production — BackgroundService из Microsoft.Extensions.Hosting.
public sealed class GracefulBackgroundWorker : IAsyncDisposable
{
    private readonly Channel<WorkUnit> _channel = Channel.CreateBounded<WorkUnit>(
        new BoundedChannelOptions(256) { FullMode = BoundedChannelFullMode.Wait });
    private readonly CancellationTokenSource _cts = new();
    private readonly Task _loop;

    public GracefulBackgroundWorker() =>
        _loop = Task.Run(() => RunAsync(_cts.Token));

    public ChannelWriter<WorkUnit> Input => _channel.Writer;

    private async Task RunAsync(CancellationToken ct)
    {
        try
        {
            await foreach (var unit in _channel.Reader.ReadAllAsync(ct).ConfigureAwait(false))
                await ProcessAsync(unit, ct).ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested) { }
    }

    public async Task StopAsync(CancellationToken ct)
    {
        _channel.Writer.TryComplete();
        _cts.Cancel();
        await _loop.WaitAsync(ct).ConfigureAwait(false);
    }

    public async ValueTask DisposeAsync() => await StopAsync(CancellationToken.None);

    private static Task ProcessAsync(WorkUnit unit, CancellationToken ct) =>
        Task.Delay(10, ct);
}
